// Variant 4: Using a method to count the occurrences of a character
import java.util.Scanner;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		String s = sc.next();
		int n = s.length();
		int count = 0, ans = 0;
		for(int i = 0; i<n; ){
			char c = s.charAt(i);
			int j = i;
			count = countOccurrences(s, c, j);
			i = j;
			if(count % 2 == 0)
				ans++;
		}
		System.out.println(ans);
	}
	public static int countOccurrences(String s, char c, int i){
		int count = 0;
		while(i < s.length() && s.charAt(i) == c){
			count++;
			i++;
		}
		return count;
	}
}
