// Variant 5: Using a method to count the occurrences of a character and a for-each loop
import java.util.Scanner;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		String s = sc.next();
		int n = s.length();
		int count = 0, ans = 0;
		for(char c : s.toCharArray()){
			int count = countOccurrences(s, c, s.indexOf(c));
			if(count % 2 == 0)
				ans++;
		}
		System.out.println(ans);
	}
	public static int countOccurrences(String s, char c, int i){
		int count = 0;
		while(i < s.length() && s.charAt(i) == c){
			count++;
			i++;
		}
		return count;
	}
}
